'use strict';
let labGroup='すべて';
const labMemory=new Map(),labPins=new Map();
const LabMath={
 seats(votes,n){const seats=votes.map(()=>0),order=[];for(let k=0;k<n;k++){let win=0;for(let i=1;i<votes.length;i++)if(votes[i]*(seats[win]+1)>votes[win]*(seats[i]+1))win=i;const divisor=seats[win]+1;seats[win]++;order.push({party:win,divisor,quotient:votes[win]/divisor})}return {seats,order}},
 allocation(weights){const sum=weights.reduce((a,b)=>a+b,0);return sum?weights.map(v=>100*v/sum):weights.map(()=>100/weights.length)},
 majority(groups,order){const ranks=[[0,1,2],[1,2,0],[2,0,1]],pairs=[[0,1],[1,2],[2,0]];const duel=(a,b)=>{let av=0,bv=0;ranks.forEach((r,i)=>{if(r.indexOf(a)<r.indexOf(b))av+=groups[i];else bv+=groups[i]});return {a,b,av,bv,winner:av===bv?null:av>bv?a:b}};const pair=pairs[order],first=duel(...pair),third=[0,1,2].find(i=>!pair.includes(i)),last=first.winner===null?null:duel(first.winner,third);return {pairs:pairs.map(p=>duel(...p)),first,last,winner:last?.winner??null}},
 average(last){const values=[2,3,4,5,last].sort((a,b)=>a-b);return {values,mean:values.reduce((a,b)=>a+b,0)/5,median:values[2]}},
 base(p){const red=1000*p/100,truePositive=red*.9,falsePositive=(1000-red)*.1;return {red,truePositive,falsePositive,posterior:truePositive/(truePositive+falsePositive)*100}},
 mix(a,b){return {a:(a*.9+(100-a)*.3),b:(b*.8+(100-b)*.2)}},
 packing(w,h,rotate){if(rotate)[w,h]=[h,w];return {w,h,cols:Math.floor(40/w),rows:Math.floor(30/h),count:Math.floor(40/w)*Math.floor(30/h)}},
 selection(p,w,t){const x=p/100*Math.pow(w,t);return 100*x/(x+1-p/100)},
 parallel(start){return Math.max(start+30,25)+5},
 clock(minutes){minutes=(Math.round(minutes)%1440+1440)%1440;return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`}
};
function labRecord(id){return LAB_EXPERIMENTS.find(e=>e.id===id)}
function labDefaults(e){return Object.fromEntries(e.controls.map(c=>[c.key,c.value]))}
function labNormalize(e,values){return Object.fromEntries(e.controls.map(c=>{let value=Number(values[c.key]);if(!Number.isFinite(value))value=c.value;const min=c.type==='select'?0:c.min,max=c.type==='select'?c.options.length-1:c.max;return [c.key,Math.max(min,Math.min(max,value))]}))}
function labPalette(e){return LAB_GROUPS.find(g=>g.name===e.group)}
function labSVG(body,label){return `<svg viewBox="0 0 600 320" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg">${body}</svg>`}
function labText(x,y,text,size=20,color='currentColor',anchor='start'){return `<text x="${x}" y="${y}" font-size="${size}" fill="${color}" text-anchor="${anchor}">${esc(text)}</text>`}
const labColors=['#378e83','#bd685d','#7971a8'];
function labBar(y,label,value,color=labColors[0],suffix='%'){return `${labText(28,y+7,label,17)}<rect x="150" y="${y-14}" width="360" height="28" rx="4" fill="currentColor" opacity=".08"/><rect x="150" y="${y-14}" width="${3.6*value}" height="28" rx="4" fill="${color}"/>${labText(535,y+7,value.toFixed(1)+suffix,17)}`}
function labDots(percent,color='#508c6b'){return Array.from({length:100},(_,i)=>`<circle cx="${78+i%10*49}" cy="${30+Math.floor(i/10)*27}" r="8" fill="${i<Math.round(percent)?color:'#c7c7c0'}"/>`).join('')}
function labModel(id,v){let body='',result='',richVisual='';
 if(id==='seats'){
  const votes=[v.a,v.b,v.c],n=v.n,{seats,order}=LabMath.seats(votes,n),total=v.a+v.b+v.c;
  body=seats.map((count,i)=>labBar(48+i*63,`${'ABC'[i]} ${count}席`,count/n*100,labColors[i])).join('');
  body+=order.map((s,i)=>`<circle cx="${45+i%10*53}" cy="${255+Math.floor(i/10)*32}" r="13" fill="${labColors[s.party]}"/>${labText(45+i%10*53,260+Math.floor(i/10)*32,'ABC'[s.party],13,'white','middle')}`).join('');
  result=`A ${seats[0]}席 / B ${seats[1]}席 / C ${seats[2]}席。得票率は ${votes.map((x,i)=>'ABC'[i]+' '+(x/total*100).toFixed(1)+'%').join('、')}。下の丸は席を得た順です。`;
 }else if(id==='budget'){
  const shares=LabMath.allocation([v.a,v.b,v.c]);body=shares.map((p,i)=>labBar(65+i*80,['学び','公園','交通'][i],p,labColors[i],'枚')).join('');
  result=shares.map((x,i)=>['学び','公園','交通'][i]+' '+x.toFixed(1)+'枚').join(' / ')+'。合計は100枚です（表示は小数1桁に丸めています）。';
 }else if(id==='majority'){
  const r=LabMath.majority([v.a,v.b,v.c],v.order);body=r.pairs.map((p,i)=>{const x=25+i*195;return `<rect x="${x}" y="35" width="170" height="185" rx="10" fill="${labColors[i]}" opacity=".15"/>${labText(x+85,90,'ABC'[p.a]+' 対 '+'ABC'[p.b],26,'currentColor','middle')}${labText(x+85,137,`${p.av} 対 ${p.bv}`,23,'currentColor','middle')}${labText(x+85,180,p.winner===null?'同票':'ABC'[p.winner]+' が多い',18,'currentColor','middle')}`}).join('');
  body+=labText(300,278,r.winner===null?'対決が同票で止まりました':'今回の順番の勝者：'+'ABC'[r.winner],26,'currentColor','middle');
  result=`人数は${v.a+v.b+v.c}人。最初の対決は${['A対B','B対C','C対A'][v.order]}。`+(r.winner===null?'同票のため勝者は決まりません。':'勝ち残り方式での最後の勝者は'+'ABC'[r.winner]+'です。');
 }else if(id==='wordorder'){
  const text=['6月10日までに、申し込みフォームを送ってください。','締め切りは6月10日です。','会場の席数を決めるために、参加人数を確認しています。'];
  // Keep each information unit independent, so only its order changes.
  text[0]='参加する方は、申し込みフォームを送ってください。';
  const order=[[0,1,2],[2,1,0],[1,0,2]][v.order];
  body=order.map((k,i)=>`<rect x="25" y="${15+i*100}" width="550" height="86" rx="8" fill="${labColors[k]}" opacity=".12"/>${labText(43,42+i*100,['すること','期限','理由'][k],16)}<foreignObject x="43" y="${51+i*100}" width="510" height="48"><div xmlns="http://www.w3.org/1999/xhtml" style="font:18px sans-serif;line-height:1.4">${esc(text[k])}</div></foreignObject>`).join('');
  richVisual='<div class="lab-word-stack">'+order.map(k=>`<div class="lab-word-unit" style="--word-ink:${labColors[k]}"><small>${['すること','期限','理由'][k]}</small>${esc(text[k])}</div>`).join('')+'</div>';
  result='最初に伝えるのは「'+['すること','理由','期限'][v.order]+'」。情報は同じで、順番だけが違います。';
 }else if(id==='ambiguity'){
  const person=(x,white)=>`<circle cx="${x}" cy="120" r="38" fill="#dbb09a"/><path d="M${x-43} 215Q${x} 155 ${x+43} 215V265H${x-43}Z" fill="#68908f"/><rect x="${x-53}" y="80" width="106" height="12" rx="5" fill="${white?'#fff':'#945756'}" stroke="#777"/><path d="M${x-33} 80v-35h66v35" fill="${white?'#fff':'#945756'}" stroke="#777"/>`;
  body=person(190,true)+person(410,v.scope===1)+labText(190,300,'女の子',18,'currentColor','middle')+labText(410,300,'男の子',18,'currentColor','middle');
  result=v.scope===0?'言い換え：白い帽子をかぶった女の子と、赤い帽子をかぶった男の子。':'言い換え：白い帽子をかぶった女の子と、同じく白い帽子をかぶった男の子。';
 }else if(id==='framing'){
  body=labDots(v.p);result=v.view===0?`${v.p}%が成功した。`:`${100-v.p}%が失敗した。`;result+=` どちらも成功${v.p}人・失敗${100-v.p}人、合計100人の同じ内訳です。`;
 }else if(id==='localtime'){
  const times=[v.hour*60-(v.mode===0?40:0),v.hour*60,v.hour*60+(v.mode===0?40:0)];
  body=times.map((m,i)=>{const x=105+i*195,angle=(m%720)/720*Math.PI*2;return `<circle cx="${x}" cy="138" r="73" fill="#fff9" stroke="currentColor" stroke-width="2"/><line x1="${x}" y1="138" x2="${x+Math.sin(angle)*43}" y2="${138-Math.cos(angle)*43}" stroke="currentColor" stroke-width="5"/><line x1="${x}" y1="138" x2="${x+Math.sin(m%60/60*Math.PI*2)*60}" y2="${138-Math.cos(m%60/60*Math.PI*2)*60}" stroke="currentColor" stroke-width="2"/>${labText(x,35,['西の町 125°','基準 135°','東の町 145°'][i],17,'currentColor','middle')}${labText(x,248,LabMath.clock(m),29,'currentColor','middle')}`}).join('');result=v.mode===0?'同じ瞬間でも、西と東の時計は80分違います。':'三つの町が同じ時刻を使うようにそろいました。';
 }else if(id==='barter'){
  body=`<path d="M120 230L300 70L480 230Z" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="8 8"/>`+[[120,230,'パン屋','欲しい：布'],[300,70,'仕立屋','欲しい：魚'],[480,230,'魚屋','欲しい：パン']].map(([x,y,name,want])=>`<circle cx="${x}" cy="${y}" r="52" fill="#fffc" stroke="currentColor"/>${labText(x,y-2,name,19,'currentColor','middle')}${labText(x,y+24,want,14,'currentColor','middle')}`).join('');
  if(v.token)body+=`<circle cx="300" cy="195" r="52" fill="#e4bc69"/>${labText(300,200,'共通の券',19,'#4b4128','middle')}`;else body+=labText(300,195,'三者同時なら？',17,'currentColor','middle');
  result=v.token?'共通の券をみんなが受け取るなら、欲しい物の一致する相手を待たず、売る時と買う時を分けられます。':'一対一では欲しい物が一致しません。ただし三者同時に輪をつくって交換する道はあります。';
 }else if(id==='evidence'){
  const papers=[['後年の回想','「5月、橋を渡った」'],['6月3日の日誌','「今日は渡り初め式」'],['4月28日の工事記録','「橋体工事、完了」']];
  body=papers.slice(0,v.set+1).map(([title,line],i)=>`<rect x="${25+i*190}" y="${35+i*14}" width="170" height="215" rx="4" fill="#fff8e8" stroke="#9e876c"/>${labText(38+i*190,78+i*14,title,14)}<foreignObject x="${38+i*190}" y="${110+i*14}" width="145" height="100"><div xmlns="http://www.w3.org/1999/xhtml" style="font:20px serif;line-height:1.7">${esc(line)}</div></foreignObject>`).join('');
  richVisual='<div><p class="lab-model-label">架空の町の資料を使った作例</p><div class="lab-paper-stack">'+papers.slice(0,v.set+1).map(([title,line])=>`<div class="lab-paper"><small>${esc(title)}</small><p>${esc(line)}</p></div>`).join('')+'</div></div>';
  result=['回想の5月だけでは、何をもって「開通」と呼んだのか分かりません。','5月と6月は矛盾でしょうか。通行した日と、式典の日が別だった可能性があります。','工事完成・実際の通行・式典。資料が記録する出来事を分けると、次に探したい証拠も変わります。'][v.set];
 }else if(id==='rgb'){
  const hex='#'+[v.r,v.g,v.b].map(x=>Math.round(x).toString(16).padStart(2,'0')).join('');
  body=`<rect x="30" y="25" width="540" height="195" rx="12" fill="${hex}" stroke="#6b7783"/>`+[v.r,v.g,v.b].map((x,i)=>`<rect x="${30+i*183}" y="240" width="173" height="40" rx="4" fill="${['#d75252','#4e9a68','#5379c1'][i]}" opacity="${.15+.85*x/255}"/>${labText(116+i*183,267,['R','G','B'][i]+' '+x,18,'white','middle')}`).join('');result=`RGB（${v.r}, ${v.g}, ${v.b}） / ${hex.toUpperCase()}。上の大きな面が、三成分を組み合わせた画面の色です。`;
 }else if(id==='perspective'){
  body=`<rect width="600" height="${v.y}" fill="#b8d6de"/><rect y="${v.y}" width="600" height="${320-v.y}" fill="#ddd2b8"/><path d="M${v.x} ${v.y}L90 320H510Z" fill="#7a8b8a"/>`+Array.from({length:9},(_,i)=>`<path d="M${v.x} ${v.y}L${-180+i*120} 320" stroke="#f8f2dd" stroke-width="1.5" opacity=".65"/>`).join('')+Array.from({length:7},(_,i)=>`<path d="M0 ${v.y+(320-v.y)*((i+1)/8)**2}H600" stroke="#577078" opacity=".6"/>`).join('')+`<path d="M0 ${v.y}H600" stroke="#52696b" stroke-dasharray="8 5"/><circle cx="${v.x}" cy="${v.y}" r="8" fill="#b9594a"/>${labText(v.x,Math.max(24,v.y-16),'消失点',18,'#753b31','middle')}`;result=`消失点は横${v.x}、地平線は高さ${v.y}。奥へ延びる線が、一つの点に集まるよう描いています。`;
 }else if(id==='composition'){
  body=`<rect width="600" height="320" fill="#d5e3df"/><circle cx="480" cy="62" r="34" fill="#f3d48f"/><path d="M0 250L140 125L280 255L440 165L600 245V320H0Z" fill="#8cafa1"/><path d="M0 280Q280 155 600 280V320H0Z" fill="#597d73"/><circle cx="${v.x}" cy="${v.y-30}" r="19" fill="#d75f4d"/><path d="M${v.x} ${v.y-10}v42m0-23-23 22m23-22 23 22m-23 1-17 35m17-35 17 35" fill="none" stroke="#d75f4d" stroke-width="10" stroke-linecap="round"/>`;
  if(v.grid===0)body+='<path d="M200 0V320M400 0V320M0 106.67H600M0 213.33H600" stroke="white" stroke-width="1.5" stroke-dasharray="5 5"/>';
  result=`主役の位置：横${Math.round(v.x/6)}%、縦${Math.round(v.y/3.2)}%。余白がどちらに広がるかを比べてみましょう。`;
 }else if(id==='packing'){
  const p=LabMath.packing(v.w,v.h,v.rotate);body='<rect x="100" y="20" width="320" height="240" rx="3" fill="#fff9" stroke="currentColor" stroke-width="3"/>';
  for(let y=0;y<p.rows;y++)for(let x=0;x<p.cols;x++)body+=`<rect x="${102+x*p.w*8}" y="${22+y*p.h*8}" width="${p.w*8-4}" height="${p.h*8-4}" rx="5" fill="#d6ab7b" stroke="#977454"/>`;
  body+=labText(260,300,'棚 40 × 30 cm',22,'currentColor','middle');result=`${p.w} × ${p.h} cmを、横${p.cols}枚 × 縦${p.rows}枚 ＝ ${p.count}枚。同じ向きの格子配置での枚数です。`;
 }else if(id==='recipe'){
  const mult=v.people/2;body=[['きゅうり',mult,'本'],['ツナ',70*mult,'g'],['しょうゆ',.5*mult,'小さじ']].map(([label,num,unit],i)=>`${labText(30,60+i*85,label,22)}<rect x="170" y="${35+i*85}" width="${90*mult}" height="32" rx="6" fill="${labColors[i]}"/>${labText(480,60+i*85,(Math.round(num*100)/100)+' '+unit,21)}`).join('');result=`${v.people}人分は、2人分の${mult.toFixed(1)}倍。きゅうり${mult}本・ツナ${70*mult}g・しょうゆ小さじ${.5*mult}です。`;
 }else if(id==='parallel'){
  const total=LabMath.parallel(v.start),scale=6.4,x=90;body=[['洗濯機',v.start,30,0],['衣類整理',0,10,1],['荷物準備',10,15,1],['仕上げ',total-5,5,2]].map(([label,start,duration,c],i)=>`${labText(10,56+i*58,label,15)}<rect x="${x+start*scale}" y="${34+i*58}" width="${duration*scale}" height="29" rx="4" fill="${labColors[c]}"/>${labText(x+start*scale+8,55+i*58,duration+'分',14,'white')}`).join('');body+=labText(90,302,'0分',16)+labText(90+60*scale,302,'60分',16);result=`すべて終わるのは${total}分後。手作業は25分、洗濯機は${v.start+30}分後に終了し、その後5分で仕上げます。`;
 }else if(id==='average'){
  const m=LabMath.average(v.last);body=m.values.map((x,i)=>`<rect x="${60+i*105}" y="${260-x*4}" width="60" height="${x*4}" rx="5" fill="${i===4?'#bd685d':'#6e9b96'}"/>${labText(90+i*105,291,x+'分',18,'currentColor','middle')}`).join('');body+=`<path d="M30 ${260-m.mean*4}H580" stroke="#a25150" stroke-width="3"/><path d="M30 ${260-m.median*4}H580" stroke="#555796" stroke-width="3" stroke-dasharray="7 5"/>${labText(30,30,'赤：平均 / 紫の点線：中央値',17)}`;result=`平均 ${m.mean.toFixed(1)}分 / 中央値 ${m.median}分。元の五つの値は ${m.values.join('、')} 分です。`;
 }else if(id==='baserate'){
  const p=LabMath.base(v.p);body=`${labText(300,47,'反応した玉だけを集めると',23,'currentColor','middle')}<rect x="40" y="80" width="520" height="68" rx="8" fill="#c9c8bf"/><rect x="40" y="80" width="${520*p.posterior/100}" height="68" rx="8" fill="#bb6258"/>${labText(40,193,'本当に赤：'+p.truePositive.toFixed(1)+'個',21,'#994b43')}${labText(40,234,'白なのに反応：'+p.falsePositive.toFixed(1)+'個',21)}${labText(300,292,'赤い玉の割合 '+p.posterior.toFixed(1)+'%',26,'currentColor','middle')}`;result=`1000個中、赤${p.red.toFixed(0)}個。反応する赤は期待値${p.truePositive.toFixed(1)}個、白は${p.falsePositive.toFixed(1)}個。反応した中で本当に赤なのは${p.posterior.toFixed(1)}%です。`;
 }else if(id==='mix'){
  const m=LabMath.mix(v.a,v.b);body=labBar(70,'Aの全体',m.a,labColors[0])+labBar(135,'Bの全体',m.b,labColors[1])+labText(30,220,'易しい課題：A 90% / B 80%',21)+labText(30,260,'難しい課題：A 30% / B 20%',21);result=`全体ではA ${m.a.toFixed(1)}%、B ${m.b.toFixed(1)}%。`+(m.a<m.b?'難易度別ではAが高いのに、全体ではBが高い組合せです。':'現在の組合せでは、全体でもAが同等以上です。');
 }else if(id==='camouflage'){
  const bg=['#879770','#bba48b','#f2ece0'][v.background];body=`<rect width="600" height="320" fill="${bg}"/>`;
  if(v.background<2)body+=Array.from({length:20},(_,i)=>`<path d="M${i*37%600} ${i*79%320}q-45-38 12-75q50 45-12 75Z" fill="${v.background===0?'#768a5d':'#a68d77'}" opacity=".65"/>`).join('');
  body+='<path d="M255 233Q155 120 351 78Q425 200 255 233Z" fill="#8a9c64" stroke="#758655" stroke-width="3"/><path d="M244 245l99-154" stroke="#6d7c51" stroke-width="3"/>';result='葉の図形と色は同じまま、背景だけを「'+['葉が茂る場所','乾いた地面','明るい無地'][v.background]+'」へ変えました。';
 }else if(id==='selection'){
  const p=LabMath.selection(v.p,v.w,v.t);body=labDots(p,'#598756');result=`${v.t}世代後の緑の割合は ${p.toFixed(1)}%。最初は${v.p}%。1世代ごとに p′ = p×w / (p×w + 1−p) で更新します。丸の数は100個に丸めた図です。`;
 }else if(id==='limiting'){
  const values=[v.a,v.b,v.c],level=Math.min(...values);body=`<rect x="165" y="${275-level*2}" width="270" height="${level*2}" fill="#7bbdc7" opacity=".7"/>`+values.map((h,i)=>`<rect x="${165+i*90}" y="${275-h*2}" width="82" height="${h*2}" rx="4" fill="#a68158" opacity=".55" stroke="#725735"/>${labText(206+i*90,305,'ABC'[i]+' '+h+'%',18,'currentColor','middle')}`).join('')+`<path d="M148 ${275-level*2}H454" stroke="#266677" stroke-width="3" stroke-dasharray="5 4"/>`;
  result=`樽にためられる上限は${level}%。今の一番低い板は${values.map((x,i)=>x===level?'ABC'[i]:'').filter(Boolean).join('・')}です。`;
 }else throw Error('Unknown lab model '+id);
 return {visual:richVisual||labSVG(body,result),result};
}
function labPoster(e){const group=labPalette(e);return `<div class="lab-poster" style="--poster-bg:${group.bg};--poster-ink:${group.ink}" aria-hidden="true"><svg viewBox="0 0 300 180"><circle cx="235" cy="35" r="90" fill="currentColor" opacity=".08"/>${e.group==='芸術とデザイン'?'<circle cx="122" cy="78" r="49" fill="#e07c65" opacity=".8"/><circle cx="168" cy="78" r="49" fill="#6e94b4" opacity=".75"/><path d="M42 140H260M100 15V160M200 15V160" stroke="currentColor" opacity=".3"/>':e.group==='社会と制度'?Array.from({length:15},(_,i)=>`<rect x="${47+i%5*43}" y="${35+Math.floor(i/5)*40}" width="29" height="27" rx="5" fill="currentColor" opacity="${.2+(i%3)*.25}"/>`).join(''):e.group==='歴史と文化'?'<rect x="62" y="35" width="96" height="120" rx="3" fill="#fffa" transform="rotate(-12 110 90)"/><rect x="135" y="25" width="96" height="120" rx="3" fill="#fffa" transform="rotate(8 180 90)"/><path d="M159 60h45m-45 18h45m-45 18h28M80 64h48m-48 18h48m-48 18h22" stroke="currentColor" stroke-width="4" opacity=".5"/>':e.group==='言葉と対話'?'<path d="M50 40h135v70H95l-30 24v-24H50Z" fill="currentColor" opacity=".25"/><path d="M125 80h125v65h-20v22l-27-22h-78Z" fill="currentColor" opacity=".55"/><path d="M72 64h84m-84 22h60m89 16h-70m70 21h-47" stroke="white" stroke-width="5"/>':e.group==='暮らしと料理'?'<rect x="57" y="34" width="187" height="120" rx="6" fill="none" stroke="currentColor" stroke-width="3"/><path d="M57 94h187M118 34v120M180 34v120" stroke="currentColor" opacity=".3"/><rect x="65" y="42" width="45" height="43" rx="5" fill="currentColor" opacity=".35"/><rect x="126" y="102" width="45" height="43" rx="5" fill="currentColor" opacity=".65"/>':e.group==='心理とデータ'?'<path d="M48 141H260" stroke="currentColor" opacity=".4"/><rect x="63" y="90" width="36" height="50" fill="currentColor" opacity=".3"/><rect x="119" y="64" width="36" height="76" fill="currentColor" opacity=".5"/><rect x="175" y="22" width="36" height="118" fill="currentColor" opacity=".7"/><path d="M38 88H260" stroke="#c06052" stroke-width="3"/>':e.group==='自然と生きもの'?'<path d="M117 146Q44 52 199 28Q239 130 117 146Z" fill="currentColor" opacity=".45"/><path d="M104 161l83-115m-52 65-32-27m49-1 29 1" stroke="currentColor" stroke-width="3"/>':'<path d="M75 30L114 130M225 30L184 130" stroke="currentColor" stroke-width="3"/><circle cx="114" cy="130" r="21" fill="currentColor" opacity=".4"/><circle cx="184" cy="130" r="21" fill="currentColor" opacity=".8"/>'}<circle cx="260" cy="145" r="12" fill="currentColor" opacity=".2"/></svg><span>${group.en}</span></div>`}
function labTile(e){const g=labPalette(e);return `<a class="lab-tile" href="#lab-${e.id}" style="--lab-ink:${g.ink}">${labPoster(e)}<div class="lab-tile-copy"><small>${esc(e.group)}</small><h2>${esc(e.title)}</h2><p>${esc(e.short)}</p><span class="lab-open">動かしてみる</span></div></a>`}
function lab(){
 const id=location.hash.startsWith('#lab-')?location.hash.slice(5):null,e=labRecord(id);
 if(e)return labDetail(e);
 const list=LAB_EXPERIMENTS.filter(e=>labGroup==='すべて'||e.group===labGroup);
 return `<div class="page lab-page"><section class="lab-cover"><div><div class="eyebrow">THE PLAYFUL MUSEUM</div><h1>「もしも」を、<br>動かしてみよう。</h1><p>言葉も、歴史も、暮らしも。<br>条件を変えると、世界の見え方が変わる。</p><div class="lab-cover-facts"><span>24の体験</span><span>8つのジャンル</span><span>正解も、宿題もなし</span></div><button class="primary" data-lab-random>今日は、偶然の扉から</button></div><div class="lab-cover-art" aria-hidden="true"><div class="lab-art-orbit"></div><span>IF</span><i class="lab-art-piece p-one"></i><i class="lab-art-piece p-two"></i><i class="lab-art-piece p-three"></i></div></section><div class="lab-guide"><p><b>変える。</b>ひとつの条件を動かす。</p><p><b>比べる。</b>この起動中の状態を残す。</p><p><b>気づく。</b>解説と行き来する。</p></div><section class="lab-directory"><div class="section-heading"><div><div class="eyebrow">PICK A LITTLE WHAT IF</div><h2>今日は、何を試そう。</h2></div><span id="lab-count">${list.length}の体験</span></div><div class="lab-filters" role="group" aria-label="実験のジャンル">${['すべて',...LAB_GROUPS.map(g=>g.name)].map(g=>`<button data-lab-filter="${g}" aria-pressed="${g===labGroup}">${g}</button>`).join('')}</div><div class="lab-gallery">${list.map(labTile).join('')}</div></section></div>`;
}
function labDetail(e){const g=labPalette(e),legacy=['pendulum','illusion','chance'].includes(e.id);return `<div class="page lab-detail" style="--lab-ink:${g.ink};--lab-bg:${g.bg}"><a class="lab-back" href="#lab">実験室の入口へ</a><div class="lab-detail-heading"><span class="eyebrow">${g.en} / ${esc(e.group)}</span><h1>${esc(e.title)}</h1><p>${esc(e.short)}</p></div><section class="lab-workshop" aria-label="${esc(e.title)}の操作体験">${legacy?'<div id="experiment" class="experiment"></div>':`<div class="lab-stage"><div id="lab-visual"></div><p id="lab-result" class="lab-result" role="status" aria-live="polite"></p></div><div class="lab-console"><h2>もし、こう変えたら？</h2><div id="lab-controls"></div><div class="lab-control-buttons"><button class="primary" id="lab-preset">試すヒントの条件にする</button><button class="secondary" id="lab-pin">いまの条件を残す</button><button class="secondary" id="lab-reset">最初の条件に戻す</button></div><p class="lab-hint">${esc(e.prompt)}</p></div>`}</section><div id="lab-comparison"></div><section class="lab-explanation"><div><div class="eyebrow">WHAT CHANGED?</div><h2>何が変わった？<br>なぜ、そうなる？</h2></div><div><p>${esc(e.explain)}</p><details><summary>この体験で扱う条件</summary><p>${esc(e.limit)}</p></details><button class="text-link" id="lab-bridge">いまの発見をGPTへコピー</button></div></section>${labMedia(e)}<section class="lab-next"><div class="section-heading"><div><div class="eyebrow">ONE MORE LITTLE DETOUR</div><h2>次は、違う角度から。</h2></div><a href="#lab">24の体験へ戻る</a></div><div class="lab-gallery">${LAB_EXPERIMENTS.filter(x=>x.id!==e.id&&x.group===e.group).concat(LAB_EXPERIMENTS.filter(x=>x.group!==e.group).slice(0,1)).slice(0,3).map(labTile).join('')}</div></section></div>`}
function labVideo(e,a){const specific=e.id==='composition'?{title:'写真家 ハービー・山口氏が語る「よりそいの構図」',provider:'キヤノン公式',url:'https://www.youtube.com/watch?v=Q71ib8jioJU',id:'Q71ib8jioJU',key:'lab-composition',language:'ja',relation:'related',checked:'2026-11-25',verification:'publisher-page',note:'写真家が構図の考え方を語る日本語映像。三分割の操作手順だけを解説する動画ではありません。'}:null;
 const civic=['seats','majority'].includes(e.id)?{title:'民主主義と選挙の原則',provider:'eboard',url:'https://www.youtube.com/watch?v=CsBVfKYOqw8',id:'CsBVfKYOqw8',language:'ja',relation:'related',checked:'2026-11-25',verification:'publisher-page',note:'日本語の社会科映像。選挙と民主主義の背景を学ぶ補足で、ドント式や多数決循環だけを扱う動画ではありません。'}:null;
 const original=specific||civic||a.videos[0],v={...original,relation:'related',articleId:a.id,image:a.image,note:(specific||civic)?.note||`「${a.title}」の関連映像です。この模型そのものの操作説明ではありません。${original.note}`};
 return v;
}
function labMedia(e){const a=data.find(a=>a.id===e.article);if(!a)return '';const v=labVideo(e,a);
 const refs=e.references.length?e.references:a.sources;
 return `<section class="lab-media"><div class="section-heading"><div><div class="eyebrow">WATCH, READ, GO FURTHER</div><h2>見て、読んで、もう少し。</h2><p>日本語で確認できる参考映像と資料。映像の対象範囲は各説明に記載しています。</p></div></div><div class="lab-media-columns"><div>${videoCard(v)}</div><div class="lab-reading"><h3>日本語の参考資料</h3>${refs.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.name)}</a>`).join('')}<button class="secondary" data-article="${e.article}">関連する展示を読む</button><p class="fine">モデル・作例：Curiosity Lab。資料の文章を再現したものではありません。参考映像の全編採点は未実施。公開元の案内確認：${e.checked}。</p></div></div></section>`;
}
function labControlHTML(e,v){return e.controls.map(c=>`<label class="lab-control" for="lab-${c.key}"><span>${esc(c.label)}${c.type==='range'?`<output id="lab-out-${c.key}" for="lab-${c.key}">${v[c.key]}${esc(c.unit)}</output>`:''}</span>${c.type==='select'?`<select id="lab-${c.key}" data-lab-value="${c.key}">${c.options.map((x,i)=>`<option value="${i}" ${v[c.key]===i?'selected':''}>${esc(x)}</option>`).join('')}</select>`:`<input type="range" id="lab-${c.key}" data-lab-value="${c.key}" min="${c.min}" max="${c.max}" step="${c.step}" value="${v[c.key]}">`}</label>`).join('')}
function setupExperiment(){
 const id=location.hash.startsWith('#lab-')?location.hash.slice(5):null,e=labRecord(id);if(!e)return;
 if(['pendulum','illusion','chance'].includes(e.id)){expType=e.id;setupLegacyExperiment();if(e.id==='illusion')$('#experiment .source-list')?.remove();}
 else{
  let values=labNormalize(e,labMemory.get(e.id)||labDefaults(e));
  function paint(){const m=labModel(e.id,values);$('#lab-visual').innerHTML=m.visual;$('#lab-result').textContent=m.result;labMemory.set(e.id,{...values});e.controls.forEach(c=>{const output=$('#lab-out-'+c.key);if(output)output.textContent=Number(values[c.key].toFixed(2))+(c.unit||'')});const pin=labPins.get(e.id);$('#lab-comparison').innerHTML=pin?`<section class="lab-previous"><div class="lab-previous-head"><h2>さっき残した条件と、比べよう。</h2><button class="secondary" id="lab-unpin">比較を閉じる</button></div><p class="fine">この起動中の比較用です。アプリを読み込み直すと消えます。</p><p>${esc(pin.conditions)}</p>${pin.visual}<p>${esc(pin.result)}</p></section>`:'';if(pin)$('#lab-unpin').onclick=()=>{labPins.delete(e.id);paint()};}
  function controls(){ $('#lab-controls').innerHTML=labControlHTML(e,values);$$('[data-lab-value]').forEach(input=>{const update=()=>{values=labNormalize(e,{...values,[input.dataset.labValue]:input.value});paint()};input.addEventListener(input.tagName==='SELECT'?'change':'input',update)}); }
  controls();paint();$('#lab-preset').onclick=()=>{values=labNormalize(e,{...values,...e.preset});controls();paint()};$('#lab-reset').onclick=()=>{values=labDefaults(e);labPins.delete(e.id);controls();paint()};$('#lab-pin').onclick=()=>{const m=labModel(e.id,values);labPins.set(e.id,{...m,conditions:e.controls.map(c=>c.label+'：'+(c.type==='select'?c.options[values[c.key]]:Number(values[c.key].toFixed(2))+(c.unit||''))).join(' / ')});paint();toast('この条件を残しました。次に条件を変えて比べてみましょう。')};
 }
 $('#lab-bridge').onclick=()=>{const values=labMemory.get(e.id)||{},conditions=e.controls.map(c=>c.label+'：'+(c.type==='select'?c.options[values[c.key]??c.value]:(values[c.key]??c.value)+(c.unit||''))).join('\n'),a=data.find(a=>a.id===e.article);copy(`【Curiosity Lab 実験室】\nテーマ：${e.title}\n操作した条件：\n${conditions||'実験画面の条件について'}\n観察：${$('#lab-result')?.textContent||e.short}\n仕組み：${e.explain}\n模型の条件：${e.limit}\n日本語の参考資料：\n${(e.references.length?e.references:a?.sources||[]).map(s=>s.name+' '+s.url).join('\n')}\n日本語の参考映像：\n${a?labVideo(e,a).title+' '+labVideo(e,a).url:''}\n依頼：この条件から何が言えて、何は言えないかを整理し、別の条件を試すならどこを変えると面白いか提案してください。実験の模型・根拠のある事実・推測を区別してください。`)};
}
document.addEventListener('click',event=>{const filter=event.target.closest('[data-lab-filter]');if(filter){labGroup=filter.dataset.labFilter;render();return}if(event.target.closest('[data-lab-random]')){const choices=LAB_EXPERIMENTS.filter(e=>labGroup==='すべて'||e.group===labGroup);location.hash='lab-'+choices[Math.floor(Math.random()*choices.length)].id;}});
